<?php
$n = (int)trim(fgets(STDIN));

$count = 0;
for ($a = 1; $a <= $n; $a++) {
    for ($b = $a; $b <= $n; $b++) {
        $c = $a ^ $b;
        if ($c < $b) continue;
        if ($c > $n) continue;
        // Check triangle inequality: a + b > c (since a <= b <= c, the other two are automatically satisfied)
        if ($a + $b > $c) {
            $count++;
        }
    }
}

echo $count . "\n";
?>
